import os, csv, json
import numpy as np

INP = "storage/noesis/nmap/nudged/scoreboard.csv"
OUTJ = "storage/noesis/nmap/nudged/correlations.json"
OUTC = "storage/noesis/nmap/nudged/correlations.csv"

def read_scoreboard(path):
    rows = []
    with open(path, 'r', encoding='utf-8') as f:
        r = csv.DictReader(f)
        for row in r:
            rows.append(row)
    return rows

def to_f(x):
    try:
        return float(x)
    except Exception:
        return np.nan

def pearson(x, y):
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    m = ~np.isnan(x) & ~np.isnan(y)
    if m.sum() < 2:
        return np.nan, (np.nan, np.nan)
    x = x[m]; y = y[m]
    r = np.corrcoef(x, y)[0,1]
    # simple linear fit y = a + b x
    A = np.vstack([np.ones_like(x), x]).T
    try:
        coef, _, _, _ = np.linalg.lstsq(A, y, rcond=None)
        a, b = coef[0], coef[1]
    except Exception:
        a, b = np.nan, np.nan
    return float(r), (float(a), float(b))

def construct_packing():
    rows = read_scoreboard(INP)
    names = [row['name'] for row in rows]
    # Collect J and deltas per ref
    refs = {
        'Noesis_243':   ('J_pairs_Noesis',   'delta_Noesis'),
        'Scientia_259': ('J_pairs_Scientia', 'delta_Scientia'),
        'Prometheus_298': ('J_pairs_Prometheus', 'delta_Prometheus')
    }
    results = {}
    out_rows = []
    for ref, (j_key, d_key) in refs.items():
        J = [to_f(row[j_key]) for row in rows]
        D = [to_f(row[d_key]) for row in rows]
        r, (a, b) = pearson(J, D)
        results[ref] = {
            'pearson_r': r,
            'linear_fit': {'a': a, 'b': b},  # delta ≈ a + b * J
            'count': int(np.sum(~np.isnan(J) & ~np.isnan(D)))
        }
        out_rows.append([ref, f"{r:.6f}", f"{a:.9f}", f"{b:.9f}", results[ref]['count']])

    os.makedirs(os.path.dirname(OUTJ), exist_ok=True)
    with open(OUTJ, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)
    with open(OUTC, 'w', encoding='utf-8', newline='') as f:
        w = csv.writer(f)
        w.writerow(['ref','pearson_r','lin_a','lin_b','count'])
        for rrow in out_rows:
            w.writerow(rrow)

    # Return a trivial valid pack (analysis-only)
    coords = [0.1,0.3,0.5,0.7,0.9]
    centers = [[x,y] for x in coords for y in coords][:25] + [[0.2,0.2]]
    radii = [0.09999]*25 + [0.0414213]
    return np.array(centers, dtype=float), np.array(radii, dtype=float)
